local handlers = {}
---@type RedDotMgr
local RedDotMgr
---@type RedDotConfig
local RedDotConfig
---@type RedDotView
local RedDotView

if isClient then
    RedDotConfig = Plugins.Require("red_dot", "client.config.red_dot_config")
    RedDotView = Plugins.Require("red_dot", "client.ui.RedDotView")
    local rdMgr = Plugins.Require("red_dot", "client.controller.RedDotMgr")
    RedDotMgr = rdMgr:getInstance()
end

function handlers.registerProfile(profile)
    RedDotMgr:registerProfile(profile)
end

---更改红点状态
function handlers.resetRedDotState(key, show)
    RedDotMgr:resetRedDotState(key, show)
end

---动态注册节点
function handlers.registerDynamicWithKey(key, parentKey, defaultShow)
    RedDotMgr:registerDynamicWithKey(key, parentKey, defaultShow or 0)
end

---关联红点变化回调函数
function handlers.linkRedDotAction(key, handler)
    RedDotMgr:linkRedDotAction(key, handler)
end

---取消关联红点回调函数
function handlers.unlinkRedDotAction(key)
    RedDotMgr:unlinkRedDotAction(key)
end

---分配一个不重复的key，如果要用就全部使用
---@param level number 结构的层级
function handlers.allocateRedDotKey(level)
    return RedDotConfig:allocateKey(level)
end

---@class RedDotBuildParams
---@field customImage string 自定义红点图片
---@field offset Vector2 红点偏移
---@field isShowNumber boolean 是否显示数字
---@field isParentBindVisible boolean 红点父控件node是否跟随红点显示/隐藏

---创建红点
---@param node GUIWindow 需要添加红点的节点对象
---@param rdKey string 绑定key值，可以为nil，nil表示创建一个不受红点系统管理的红点
---@param parentKey string 父亲key值,可以为nil
---@param params RedDotBuildParams 红点展示的样式配置，比如图片，偏移
function handlers.redDotBuild(node, rdKey, parentKey, params)
    params = params or {}
    local customImage = params.customImage or "set:bed_war_3_common_part.json image:img_0_red_dot03"
    local offset = params.offset or { x = 0, y = 0 }
    local isShowNumber = params.isShowNumber or false
    local isParentBindVisible = params.isParentBindVisible or false
    RedDotView.builder(rdKey, parentKey)
              :setIsShowNumber(isShowNumber)
              :setIsParentBindVisible(isParentBindVisible)
              :setCustomImage(customImage)
              :setOffset(offset)
              :show(node)
end

return function(name, ...)
    if type(handlers[name]) ~= "function" then
        return
    end
    handlers[name](...)
end